package controller; import dao.*; import model.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; import java.math.*; import java.util.*; public class VendorItemServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{int id=(Integer)r.getSession().getAttribute("vendorId");r.setAttribute("inventory",new VendorItemDAO().getInventoryByVendor(id));r.getRequestDispatcher("/vendorItems.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{int v=(Integer)r.getSession().getAttribute("vendorId"),i=Integer.parseInt(r.getParameter("itemId"));BigDecimal price=new BigDecimal(r.getParameter("price"));int stock=Integer.parseInt(r.getParameter("stock"));boolean a="true".equals(r.getParameter("available"));new VendorItemDAO().updateVendorItem(v,i,price,stock,a);s.sendRedirect(r.getContextPath()+"/VendorItemServlet");}catch(Exception e){throw new ServletException(e);}}}